-- Rule: always lock the two accounts in ascending id order,
-- regardless of which is the source or destination.
BEGIN;
SELECT id FROM accounts
WHERE id IN ('A','B')
ORDER BY id            -- deterministic order: A then B
FOR UPDATE;            -- lock both rows up front, in order

UPDATE accounts SET balance = balance - 100 WHERE id = 'A';
UPDATE accounts SET balance = balance + 100 WHERE id = 'B';
COMMIT;

-- Pseudocode (any language / driver):
MAX_RETRIES = 5
for attempt in 1..MAX_RETRIES:
    try:
        BEGIN;
        -- ... do the transfer, locking rows in canonical order ...
        COMMIT;
        break                      -- success
    except DatabaseError as e:
        ROLLBACK;
        if e.sqlstate in ('40P01',  -- deadlock_detected (PostgreSQL)
                          '40001'): -- serialization_failure
            sleep(random_jitter(2 ** attempt * BASE_MS))  -- backoff
            continue               -- retry the WHOLE transaction
        else:
            raise                  -- non-retryable: propagate
